'use client'

import { useId } from 'react'
import './case-study-story.css'

export interface CaseStudyImage {
  src: string
  alt: string
  caption?: string
}

export interface CaseStudyFact {
  label: string
  value: string
}

export interface CaseStudyChapter {
  id: string
  title: string
  paragraphs: string[]
  image?: CaseStudyImage
}

export interface CaseStudyOutcome {
  value: string
  label: string
}

export interface CaseStudyNextProject {
  title: string
  href: string
  label?: string
  image?: CaseStudyImage
}

export interface CaseStudyStoryProps {
  title: string
  intro: string
  hero: CaseStudyImage
  chapters: CaseStudyChapter[]
  eyebrow?: string
  facts?: CaseStudyFact[]
  outcomes?: CaseStudyOutcome[]
  outcomesTitle?: string
  outcomeNote?: string
  nextProject?: CaseStudyNextProject
  showChapterLinks?: boolean
  className?: string
}

function StoryImage({ image, className = '' }: { image: CaseStudyImage; className?: string }) {
  return <figure className={`ac-case-image ${className}`.trim()}><img src={image.src} alt={image.alt} loading="lazy" />{image.caption && <figcaption>{image.caption}</figcaption>}</figure>
}

/** An editorial project story with readable chapters, project facts, and outcomes. */
export function CaseStudyStory({ title, intro, hero, chapters, eyebrow = 'SELECTED WORK', facts = [], outcomes = [], outcomesTitle = 'The outcome.', outcomeNote, nextProject, showChapterLinks = true, className = '' }: CaseStudyStoryProps) {
  const id = useId()
  return <article className={`ac-case-study ${className}`.trim()} aria-labelledby={`${id}-title`}>
    <header className="ac-case-header">
      <div className="ac-case-topline"><span>{eyebrow}</span><span aria-hidden="true">A CLOSER LOOK / ↘</span></div>
      <h2 id={`${id}-title`}>{title}</h2>
      <div className="ac-case-intro"><p>{intro}</p>{facts.length > 0 && <dl className="ac-case-facts">{facts.map((fact, index) => <div key={`${fact.label}-${index}`}><dt>{fact.label}</dt><dd>{fact.value}</dd></div>)}</dl>}</div>
    </header>
    <StoryImage image={hero} className="ac-case-hero" />
    {showChapterLinks && chapters.length > 0 && <nav className="ac-case-chapter-links" aria-label={`${title} chapters`}><span>IN THIS STORY</span><ol>{chapters.map((chapter, index) => <li key={chapter.id}><a href={`#${id}-${chapter.id}`}><span aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>{chapter.title}</a></li>)}</ol></nav>}
    <div className="ac-case-chapters">{chapters.map((chapter, index) => <section key={chapter.id} id={`${id}-${chapter.id}`} className="ac-case-chapter" aria-labelledby={`${id}-${chapter.id}-title`}>
      <div className="ac-case-chapter-text"><header><span className="ac-case-index" aria-hidden="true">/{String(index + 1).padStart(2, '0')}</span><h3 id={`${id}-${chapter.id}-title`}>{chapter.title}</h3></header><div className="ac-case-prose">{chapter.paragraphs.map((paragraph, paragraphIndex) => <p key={paragraphIndex}>{paragraph}</p>)}</div></div>
      {chapter.image && <StoryImage image={chapter.image} className="ac-case-chapter-image" />}
    </section>)}</div>
    {outcomes.length > 0 && <section className="ac-case-outcomes" aria-label="Project outcomes"><header><span>IN THE DETAILS</span><h3>{outcomesTitle}</h3>{outcomeNote && <p>{outcomeNote}</p>}</header><dl>{outcomes.map((outcome, index) => <div key={`${outcome.label}-${index}`}><dt>{outcome.label}</dt><dd>{outcome.value}</dd></div>)}</dl></section>}
    {nextProject && <a className="ac-case-next" href={nextProject.href}>{nextProject.image && <img src={nextProject.image.src} alt={nextProject.image.alt} loading="lazy" />}<div><span>{nextProject.label ?? 'NEXT PROJECT'}</span><h3>{nextProject.title}</h3></div><span className="ac-case-next-arrow" aria-hidden="true">↗</span></a>}
  </article>
}

.ac-case-study {
  --ac-case-surface: #f1f0e7;
  --ac-case-ink: #343b30;
  --ac-case-muted: #707664;
  --ac-case-line: #343b3028;
  --ac-case-accent: #dfe4d1;
  container: ac-case / inline-size;
  width: 100%;
  max-width: 1920px;
  margin-inline: auto;
  background: var(--ac-case-surface);
  color: var(--ac-case-ink);
  font-family: var(--sans, Arial, sans-serif);
  text-align: left;
}
.ac-case-study *, .ac-case-study *::before, .ac-case-study *::after { box-sizing: border-box; }
.ac-case-header { padding: clamp(25px, 4cqi, 72px) clamp(24px, 5cqi, 96px) clamp(30px, 4cqi, 66px); }
.ac-case-topline { display: flex; justify-content: space-between; gap: 15px; color: var(--ac-case-muted); font-size: clamp(9px, .7cqi, 12px); line-height: 1.5; letter-spacing: .09em; }
.ac-case-topline > span:last-child { text-align: right; }
.ac-case-header h2 { max-width: 13ch; margin: clamp(35px, 5.3cqi, 92px) 0 clamp(30px, 3.8cqi, 65px); font-family: var(--serif, Georgia, serif); font-size: clamp(54px, 10.2cqi, 164px); line-height: .92; font-weight: 400; letter-spacing: -.065em; white-space: pre-line; overflow-wrap: anywhere; }
.ac-case-intro { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 7cqi, 130px); align-items: start; }
.ac-case-intro > p { max-width: 41ch; margin: 0; font-size: clamp(15px, 1.5cqi, 24px); line-height: 1.55; letter-spacing: -.02em; }
.ac-case-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 26px; margin: 0; }
.ac-case-facts dt { margin-bottom: 6px; color: var(--ac-case-muted); font-size: clamp(9px, .65cqi, 11px); line-height: 1.5; text-transform: uppercase; letter-spacing: .08em; }
.ac-case-facts dd { margin: 0; font-size: clamp(11px, .85cqi, 14px); line-height: 1.55; overflow-wrap: anywhere; }
.ac-case-image { margin: 0; }
.ac-case-image img { display: block; width: 100%; object-fit: cover; }
.ac-case-hero { padding-inline: clamp(12px, 1.2cqi, 24px); }
.ac-case-hero img { height: clamp(280px, 52cqi, 820px); object-position: 50% 56%; }
.ac-case-image figcaption { display: flex; padding-block: 12px; color: var(--ac-case-muted); font-size: clamp(9px, .67cqi, 11px); line-height: 1.6; letter-spacing: .025em; }
.ac-case-chapter-links { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-inline: clamp(24px, 5cqi, 96px); padding-block: 25px; border-bottom: 1px solid var(--ac-case-line); }
.ac-case-chapter-links > span { flex-shrink: 0; padding-top: 10px; color: var(--ac-case-muted); font-size: 9px; line-height: 1.5; letter-spacing: .08em; }
.ac-case-chapter-links ol { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 8px 30px; padding: 0; margin: 0; list-style: none; }
.ac-case-study a { color: inherit; text-decoration: none; }
.ac-case-study a:focus-visible { outline: 2px solid var(--ac-case-ink); outline-offset: 5px; }
.ac-case-chapter-links a { display: flex; align-items: center; gap: 10px; min-height: 44px; scroll-margin-block: 12px; font-size: clamp(11px, .8cqi, 13px); }
.ac-case-chapter-links a > span { color: var(--ac-case-muted); font-size: 9px; }
.ac-case-chapter-links a:hover { text-decoration: underline; text-underline-offset: 5px; }
.ac-case-chapters { padding-inline: clamp(24px, 5cqi, 96px); }
.ac-case-chapter { padding-block: clamp(38px, 5cqi, 85px); border-bottom: 1px solid var(--ac-case-line); scroll-margin-top: 24px; }
.ac-case-chapter-text { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(30px, 7cqi, 130px); }
.ac-case-chapter-text > header { display: flex; align-items: flex-start; gap: clamp(20px, 3cqi, 48px); }
.ac-case-index { margin-top: 8px; color: var(--ac-case-muted); font-size: clamp(10px, .8cqi, 13px); }
.ac-case-chapter h3 { max-width: 14ch; margin: 0; font-family: var(--serif, Georgia, serif); font-size: clamp(32px, 3.6cqi, 58px); line-height: 1.07; font-weight: 400; letter-spacing: -.04em; }
.ac-case-prose { max-width: 54ch; font-size: clamp(13px, 1cqi, 16px); line-height: 1.8; }
.ac-case-prose p { margin: 0 0 1.2em; }
.ac-case-prose p:last-child { margin-bottom: 0; }
.ac-case-chapter-image { width: 72%; margin: clamp(28px, 3.7cqi, 60px) 0 0 auto; }
.ac-case-chapter-image img { height: clamp(240px, 36cqi, 580px); object-position: 74% 60%; }
.ac-case-outcomes { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(35px, 7cqi, 130px); margin: clamp(32px, 5cqi, 80px) clamp(24px, 5cqi, 96px); padding: clamp(28px, 4cqi, 65px); background: var(--ac-case-accent); }
.ac-case-outcomes > header > span { font-size: 9px; letter-spacing: .08em; }
.ac-case-outcomes h3 { margin: 22px 0; font-family: var(--serif, Georgia, serif); font-size: clamp(35px, 4cqi, 64px); line-height: 1.02; font-weight: 400; letter-spacing: -.05em; white-space: pre-line; }
.ac-case-outcomes > header > p { max-width: 38ch; margin: 0; color: var(--ac-case-muted); font-size: clamp(11px, .8cqi, 13px); line-height: 1.65; }
.ac-case-outcomes dl { display: grid; gap: 20px; margin: 0; }
.ac-case-outcomes dl > div { display: flex; align-items: baseline; justify-content: space-between; gap: 25px; padding-bottom: 18px; border-bottom: 1px solid var(--ac-case-line); }
.ac-case-outcomes dt { max-width: 22ch; font-size: clamp(11px, .8cqi, 13px); line-height: 1.5; }
.ac-case-outcomes dd { order: -1; margin: 0; font-size: clamp(34px, 4.4cqi, 70px); line-height: 1; letter-spacing: -.07em; }
.ac-case-next { display: flex; align-items: center; gap: clamp(20px, 3cqi, 48px); margin-inline: clamp(24px, 5cqi, 96px); padding-block: clamp(24px, 3cqi, 48px); border-top: 1px solid var(--ac-case-line); }
.ac-case-next > img { width: 24%; max-width: 240px; aspect-ratio: 1.5; object-fit: cover; }
.ac-case-next > div { min-width: 0; }
.ac-case-next > div > span { color: var(--ac-case-muted); font-size: 9px; letter-spacing: .08em; }
.ac-case-next h3 { margin: 10px 0 0; font-family: var(--serif, Georgia, serif); font-size: clamp(30px, 3.8cqi, 60px); line-height: 1.05; font-weight: 400; letter-spacing: -.04em; overflow-wrap: anywhere; }
.ac-case-next-arrow { margin-left: auto; font-size: clamp(35px, 4cqi, 64px); transition: transform .2s; }
.ac-case-next:hover .ac-case-next-arrow { transform: translate(3px, -3px); }
@container ac-case (max-width: 650px) {
  .ac-case-header h2 { font-size: clamp(52px, 11.4cqi, 74px); }
  .ac-case-intro, .ac-case-chapter-text, .ac-case-outcomes { grid-template-columns: 1fr; gap: 28px; }
  .ac-case-intro > p { max-width: 40ch; }
  .ac-case-facts { padding-top: 20px; border-top: 1px solid var(--ac-case-line); }
  .ac-case-hero img { height: 76cqi; min-height: 260px; }
  .ac-case-chapter-links { flex-direction: column; gap: 9px; padding-block: 16px; }
  .ac-case-chapter-links ol { justify-content: flex-start; gap: 0 22px; }
  .ac-case-chapter-text > header { gap: 22px; }
  .ac-case-chapter h3 { max-width: 20ch; }
  .ac-case-chapter-image { width: 100%; }
  .ac-case-chapter-image img { min-height: 260px; height: 70cqi; }
  .ac-case-next { flex-wrap: wrap; }
  .ac-case-next > img { width: 100%; max-width: none; height: 170px; }
}
@media (prefers-reduced-motion: reduce) {
  .ac-case-next-arrow { transition: none; }
  .ac-case-next:hover .ac-case-next-arrow { transform: none; }
}
